CREATE VIEW [purchase].[SupplierLedger] AS SELECT i.SupplierId,i.PurchaseInvoiceId ReferenceId,i.InvoiceDate EntryDate,i.InvoiceNumber ReferenceNumber,CAST('PURCHASE' AS NVARCHAR(20))EntryType,i.GrandTotal Debit,CAST(0 AS DECIMAL(18,2))Credit FROM purchase.PurchaseInvoices i WHERE i.IsDeleted=0 AND i.Status NOT IN('DRAFT','CANCELLED') UNION ALL SELECT i.SupplierId,p.PurchaseInvoiceId,p.PaymentDate,p.ReferenceNumber,'PAYMENT',0,p.Amount FROM purchase.PurchasePayments p JOIN purchase.PurchaseInvoices i ON i.PurchaseInvoiceId=p.PurchaseInvoiceId WHERE p.Status='COMPLETED' UNION ALL SELECT i.SupplierId,r.PurchaseInvoiceId,r.ReturnDate,r.ReturnNumber,'RETURN',0,r.AdjustmentAmount FROM purchase.PurchaseReturns r JOIN purchase.PurchaseInvoices i ON i.PurchaseInvoiceId=r.PurchaseInvoiceId;
